  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView title=new TextView(this);title.setText("厚涂小站  ·  手机本地");title.setTextSize(18);title.setPadding(dp(18),0,0,0);top.addView(title,new LinearLayout.LayoutParams(0,dp(52),1));Button more=new Button(this);more.setText("更多");more.setContentDescription("更多工作台与应用设置");more.setOnClickListener(v->menu(more));top.addView(more,new LinearLayout.LayoutParams(dp(72),dp(48)));root.addView(top);
  message=new TextView(this);message.setText("正在启动手机图片引擎…\n首次启动需要整理本机资源。");message.setTextSize(16);message.setGravity(Gravity.CENTER);message.setPadding(dp(24),dp(32),dp(24),dp(32));root.addView(message,new LinearLayout.LayoutParams(-1,0,1));
  web=new WebView(this);settings(web);web.setVisibility(View.GONE);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String url=r.getUrl().toString();if(own(url))return false;if(r.isForMainFrame()&&r.hasGesture())openExternal(url);return true;}public void onPageFinished(WebView v,String u){if(own(u))attachDownloads();}public void onReceivedSslError(WebView v,android.webkit.SslErrorHandler h,android.net.http.SslError e){h.cancel();}});
