   public boolean onCreateWindow(WebView view,boolean dialog,boolean user,android.os.Message result){if(!user||!own(view.getUrl()))return false;WebView popup=new WebView(MainActivity.this);popup.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String url){openExternal(url);v.destroy();return true;}});((WebView.WebViewTransport)result.obj).setWebView(popup);result.sendToTarget();return true;}
