 void settings(WebView v){WebSettings s=v.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(true);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setMediaPlaybackRequiresUserGesture(true);s.setOffscreenPreRaster(true);CookieManager.getInstance().setAcceptThirdPartyCookies(v,false);}
 void runtimeReady(){if(ready||isFinishing())return;ready=true;CookieManager.getInstance().setCookie(RuntimeHost.origin,"houtu_local="+RuntimeHost.token+"; Path=/; HttpOnly; SameSite=Strict",ok->{message.setVisibility(View.GONE);web.setVisibility(View.VISIBLE);nav.setVisibility(View.VISIBLE);web.loadUrl(RuntimeHost.origin+"/");engine=new WebView(this);settings(engine);engine.setAlpha(0);root.addView(engine,new LinearLayout.LayoutParams(1,1));engine.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !own(r.getUrl().toString());}public void onPageFinished(WebView v,String u){if(own(u))RuntimeHost.broker.attach(v,RuntimeHost.origin);}});engine.loadUrl(RuntimeHost.origin+"/vision-target.html");});}
 void runtimeFailed(String error){message.setVisibility(View.VISIBLE);message.setText("本机图片引擎尚未启动\n\n"+error+"\n\n可在“更多 → 复制诊断”查看状态。");}
 boolean own(String value){if(value==null||RuntimeHost.origin==null)return false;try{Uri a=Uri.parse(value),b=Uri.parse(RuntimeHost.origin);return a.getScheme().equals(b.getScheme())&&a.getHost().equals(b.getHost())&&a.getPort()==b.getPort();}catch(Exception e){return false;}}
 void go(String path){if(ready)web.loadUrl(RuntimeHost.origin+path);}
 void openExternal(String value){try{Uri uri=Uri.parse(value);if(!"https".equals(uri.getScheme())){toast("仅支持打开 HTTPS 网页。");return;}startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){toast("此手机没有可用的浏览器。");}}
 void menu(View anchor){PopupMenu p=new PopupMenu(this,anchor);String[] titles={"特效与合成","工作流管理","图片档案","提示词实验室","检查安卓版更新","分享最近成片","复制诊断"};for(int i=0;i<titles.length;i++)p.getMenu().add(0,i,i,titles[i]);p.setOnMenuItemClickListener(item->{switch(item.getItemId()){case 0:go("/creative/");break;case 1:go("/workflows/");break;case 2:go("/server/");break;case 3:go("/lab/");break;case 4:AndroidUpdates.check(this);break;case 5:if(lastSaved!=null){Intent share=new Intent(Intent.ACTION_SEND).setType(lastMime).putExtra(Intent.EXTRA_STREAM,lastSaved).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"分享成片"));}else toast("保存一张成片后可分享。");break;case 6:copy("厚涂小站 Android\n系统 "+Build.VERSION.RELEASE+" / "+Build.SUPPORTED_ABIS[0]+"\n运行时 "+(RuntimeHost.error!=null?RuntimeHost.error:ready?"已启动":"准备中")+"\n数据位于本应用私有目录，不依赖电脑。");break;}return true;});p.show();}
 void attachDownloads(){if(!own(web.getUrl()))return;String script="window.addEventListener('message',e=>{if(e.data!=='houtu-documents')return;window.houtuDocuments=e.ports[0];});";web.evaluateJavascript(script,unused->{WebMessagePort[] ports=web.createWebMessageChannel();ports[0].setWebMessageCallback(new WebMessagePort.WebMessageCallback(){public void onMessage(WebMessagePort port,WebMessage m){if(!own(web.getUrl()))return;String raw=m.getData();if(raw==null||raw.length()>90*1024*1024)return;RuntimeHost.broker.pool.execute(()->{try{JSONObject q=new JSONObject(raw);if(q.optString("type").equals("open")){String url=q.optString("url");runOnUiThread(()->openExternal(url));return;}if(q.optString("type").equals("copy")){String text=q.optString("text");if(text.length()<30000)runOnUiThread(()->copy(text));return;}String data=q.getString("data");int comma=data.indexOf(',');if(comma<0||!data.substring(0,comma).contains(";base64"))throw new IOException("下载内容无效。");byte[] bytes=android.util.Base64.decode(data.substring(comma+1),android.util.Base64.DEFAULT);if(bytes.length>64*1024*1024)throw new IOException("文件较大，请使用工作流成片下载。");String name=q.optString("name","成片.png"),mime=q.optString("mime","application/octet-stream");runOnUiThread(()->chooseSave(name,mime,null,bytes));}catch(Exception e){runOnUiThread(()->toast("文件保存未完成："+e.getMessage()));}});}});web.postWebMessage(new WebMessage("houtu-documents",new WebMessagePort[]{ports[1]}),Uri.parse(RuntimeHost.origin));});}
 void chooseSave(String name,String mime,String url,byte[] bytes){if(downloadUrl!=null||downloadBytes!=null){toast("请先完成当前文件保存。");return;}downloadUrl=url;downloadBytes=bytes;downloadMime=mime==null?"application/octet-stream":mime;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(downloadMime).putExtra(Intent.EXTRA_TITLE,name.replaceAll("[\\\\/\\r\\n]","_").substring(0,Math.min(160,name.length())));try{startActivityForResult(i,2);}catch(Exception e){downloadUrl=null;downloadBytes=null;toast("无法打开系统保存位置。");}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==4){AndroidUpdates.resumed(this);return;}if(request==1){ValueCallback<Uri[]> callback=chooser;chooser=null;if(callback==null)return;if(result!=RESULT_OK||data==null){callback.onReceiveValue(null);return;}ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++){Uri u=data.getClipData().getItemAt(i).getUri();if("content".equals(u.getScheme()))uris.add(u);}else if(data.getData()!=null&&"content".equals(data.getData().getScheme()))uris.add(data.getData());callback.onReceiveValue(uris.isEmpty()?null:uris.toArray(new Uri[0]));}
  if(request==2){String url=downloadUrl,mime=downloadMime;byte[] bytes=downloadBytes;downloadUrl=null;downloadBytes=null;if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri destination=data.getData();RuntimeHost.broker.pool.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(destination,"w")){if(out==null)throw new IOException("无法写入所选位置。");if(bytes!=null)out.write(bytes);else{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestProperty("Authorization","Bearer "+RuntimeHost.token);c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(120000);try{if(c.getResponseCode()!=200)throw new IOException("成片暂不可用，请重新打开结果。");try(InputStream in=c.getInputStream()){RuntimeHost.copy(in,out,3L*1024*1024*1024);}}finally{c.disconnect();}}lastSaved=destination;lastMime=mime;runOnUiThread(()->toast("已保存，可在“更多”中分享成片。"));}catch(Exception e){runOnUiThread(()->toast("保存未完成："+e.getMessage()));}});}}
 void copy(String text){android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("厚涂小站",text));toast("已复制。");}void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
